/** Private state/DB and fake clock/scheduler/notification/re-ring. Never launches AlarmActivity or posts notifications. */
@org.junit.runner.RunWith(androidx.test.ext.junit.runners.AndroidJUnit4.class)
public class WakeCheckFlowTest {
 private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private WakeCheckActivity activity;
 static final class Clock implements WakeCheckState.Clock {long wall=1792824000000L,elapsed=500000,boot=4;public long wall(){return wall;}public long elapsed(){return elapsed;}public long boot(){return boot;}void advance(long ms){wall+=ms;elapsed+=ms;}}
 private final class Fixture implements AutoCloseable {
  final String name="wake-check-"+UUID.randomUUID(),database=name+".db";final Clock clock=new Clock();final WakeCheckStorage storage=new WakeCheckStorage(c.getSharedPreferences(name,Context.MODE_PRIVATE));final List<Activity> owned=new CopyOnWriteArrayList<>();final Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());final WakeChecks.Factory oldFactory=WakeChecks.factory;final Function<Context,WakeCheckState.Clock> oldClocks=WakeChecks.clocks;final Application app=(Application)c.getApplicationContext();final String nonce=UUID.randomUUID().toString();final Alarm alarm=new Alarm(1);String before;final WakeCheckEngine engine;final Records.Factory oldRecords=Records.factory;final AlarmScheduling.Port oldScheduling=AlarmScheduling.port;boolean allow=true,failShow,failAlarmSave;String run="native-occurrence";int shown,rings,schedules,cancels;long scheduledDelay;WakeCheckEngine.Stage stage;
  final Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue("Check and inert editor only",a instanceof WakeCheckActivity||a instanceof AlarmEditorActivity||a instanceof WakeCheckPracticeActivity);owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){if(a instanceof WakeCheckActivity)activity=(WakeCheckActivity)a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
  Fixture()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));alarm.enabled=false;alarm.awakeCheck=1;alarm.label="Workdays";try(Store store=new Store(c,database)){store.save(alarm);Alarm other=new Alarm(2);other.enabled=false;other.label="Untouched private fixture";store.save(other);before=store.backup().toString();}
   engine=new WakeCheckEngine(storage,new WakeCheckEngine.Port(){public boolean owner(WakeCheckState s){try(Store store=new Store(c,database)){Alarm current=store.alarm(s.alarmId);return run.equals(s.run)&&current!=null&&current.awakeCheck>0;}}public String access(){return allow?"":"Allow notifications to receive the silent check.";}public void schedule(WakeCheckState s,WakeCheckEngine.Stage requested,long delay){schedules++;stage=requested;scheduledDelay=delay;}public void cancel(WakeCheckState s){cancels++;}public void show(WakeCheckState s){if(failShow)throw new IllegalStateException("injected delivery failure");shown++;}public void ring(WakeCheckState s){assertEquals(WakeCheckState.Phase.CLAIMED,storage.load().phase);rings++;}},clock);app.registerActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{WakeChecks.factory=context->engine;WakeChecks.clocks=context->clock;Records.factory=context->new Store(context,database){@Override public void save(Alarm edited){if(failAlarmSave&&edited.id==1&&edited.awakeCheck==0)throw new SecurityException("Injected alarm save failure");super.save(edited);}};AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm a){assertFalse(a.enabled);}};});}
  void arm(){engine.arm(WakeCheckState.waiting(nonce,run,alarm.json().toString(),alarm.label,alarm.id,60000,false,clock));}
  @Override public void close()throws Exception{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));try(Store store=new Store(c,database)){assertEquals("Reviewed configuration and original records/unrelated alarms remain intact",before,store.backup().toString());}assertEquals(original,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{WakeChecks.factory=oldFactory;WakeChecks.clocks=oldClocks;Records.factory=oldRecords;AlarmScheduling.port=oldScheduling;});if(owned.stream().allMatch(Activity::isDestroyed)){c.deleteDatabase(database);c.deleteSharedPreferences(name);}}}
 }
 private <T>T read(java.util.function.Supplier<T> action){java.util.concurrent.atomic.AtomicReference<T> value=new java.util.concurrent.atomic.AtomicReference<>();i.runOnMainSync(()->value.set(action.get()));return value.get();}
 @SuppressWarnings("unchecked") private <T>T field(Object object,String name){try{java.lang.reflect.Field value=object.getClass().getDeclaredField(name);value.setAccessible(true);return (T)value.get(object);}catch(ReflectiveOperationException missing){throw new AssertionError(name,missing);}}
 private void focused(Activity owner){long until=SystemClock.elapsedRealtime()+5000;while(!read(()->owner!=null&&!owner.isDestroyed()&&!owner.isFinishing()&&owner.hasWindowFocus()&&owner.getWindow().getDecorView().isLaidOut()&&!owner.getWindow().getDecorView().isLayoutRequested())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(30);assertTrue("Actual current focused owner",read(()->owner!=null&&!owner.isDestroyed()&&!owner.isFinishing()&&owner.hasWindowFocus()&&owner.getWindow().getDecorView().isLaidOut()&&!owner.getWindow().getDecorView().isLayoutRequested()));}
 private String route(AlarmEditorActivity owner){return read(()->field(owner,"route"));}
 private String draft(AlarmEditorActivity owner){return read(()->((Alarm)field(owner,"alarm")).json().toString());}
 private <T extends Activity>T recreateOwner(T owner,Class<T> type)throws Exception{Instrumentation.ActivityMonitor m=i.addMonitor(type.getName(),null,false);try{i.runOnMainSync(owner::recreate);T next=type.cast(m.waitForActivityWithTimeout(5000));assertNotNull(next);awaitDestroyed(owner);focused(next);return next;}finally{i.removeMonitor(m);}}
 private WakeCheckPracticeActivity preview()throws Exception{Instrumentation.ActivityMonitor m=i.addMonitor(WakeCheckPracticeActivity.class.getName(),null,false);try{click("Preview wake-up check");WakeCheckPracticeActivity next=(WakeCheckPracticeActivity)m.waitForActivityWithTimeout(5000);assertNotNull(next);focused(next);return next;}finally{i.removeMonitor(m);}}
 private void delay(int minutes)throws Exception{click("Wake-up check");assertTrue(device.wait(Until.hasObject(By.desc("Options for Wake-up check")),3000));String label=minutes==0?"Off":"After "+minutes+" min";UiObject2 option=device.wait(Until.findObject(By.desc(label)),1000);if(option==null){UiScrollable options=new UiScrollable(new UiSelector().description("Options for Wake-up check"));assertTrue(options.scrollIntoView(new UiSelector().description(label)));option=device.wait(Until.findObject(By.desc(label)),3000);}assertNotNull(label,option);option.click();assertTrue(device.wait(Until.gone(By.desc("Options for Wake-up check")),3000));i.waitForIdleSync();}
 private void practiceFrame(Activity owner,String suffix)throws Exception{focused(owner);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View root=owner.getWindow().getDecorView();if(owner instanceof WakeCheckPracticeActivity){android.widget.LinearLayout footer=root.findViewWithTag("wake-check-practice-footer");assertNotNull(footer);for(int n=0;n<footer.getChildCount();n++){View child=footer.getChildAt(n);android.graphics.Rect area=new android.graphics.Rect();assertTrue(child.getGlobalVisibleRect(area));assertEquals(child.getWidth(),area.width());assertEquals(child.getHeight(),area.height());assertTrue(area.width()>=Design.dp(c,48)&&area.height()>=Design.dp(c,48));}android.widget.ScrollView scroll=(android.widget.ScrollView)((android.widget.LinearLayout)footer.getParent()).getChildAt(0);assertTrue("Practice retains a usable inset-safe reading viewport",scroll.getHeight()>=Design.dp(c,200));}root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));focused(owner);File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"wake-check-practice-"+suffix+".png")));}
 @Test public void settingsPracticePreviewAcknowledgesAndReturnsUnchangedDraftWithoutOpeningCheck()throws Exception{
  try(Fixture f=new Fixture()){
   java.util.concurrent.atomic.AtomicInteger engineOpens=new java.util.concurrent.atomic.AtomicInteger(),clockOpens=new java.util.concurrent.atomic.AtomicInteger(),alarmSchedules=new java.util.concurrent.atomic.AtomicInteger();
   i.runOnMainSync(()->{WakeChecks.factory=context->{engineOpens.incrementAndGet();throw new AssertionError("Practice must not open a real check engine");};WakeChecks.clocks=context->{clockOpens.incrementAndGet();throw new AssertionError("Practice must not open the runtime check clock");};AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm a){alarmSchedules.incrementAndGet();throw new AssertionError("Practice must not schedule an alarm");}};});
   AlarmEditorActivity owner=editor(f.alarm);focused(owner);click("Snooze");delay(7);String pending=draft(owner);assertEquals(7,Alarm.read(new org.json.JSONObject(pending)).awakeCheck);
   WakeCheckPracticeActivity practice=preview();text("Draft delay · After 7 min");text("Example · no running countdown");text("Practice only");practiceFrame(practice,"ready");
   practice=recreateOwner(practice,WakeCheckPracticeActivity.class);text("Draft delay · After 7 min");text("Still awake?");practiceFrame(practice,"recreated");
   click("Practice acknowledgement");text("Practice acknowledgement received");practiceFrame(practice,"acknowledged");practice=recreateOwner(practice,WakeCheckPracticeActivity.class);text("Practice acknowledgement received");assertFalse(device.hasObject(By.text("Practice acknowledgement")));
   click("Return to wake-up settings");awaitDestroyed(practice);focused(owner);assertEquals("Practice return retains every unsaved alarm field",pending,draft(owner));assertEquals("snooze",route(owner));practiceFrame(owner,"returned");
   owner=recreateOwner(owner,AlarmEditorActivity.class);assertEquals("Settings recreation retains the complete delay-seven draft",pending,draft(owner));assertEquals("snooze",route(owner));practiceFrame(owner,"settings-recreated");
   delay(0);String off=draft(owner);practice=preview();text("Wake-up check is Off in your draft");practiceFrame(practice,"off");click("Practice acknowledgement");text("Practice acknowledgement received");click("Return to wake-up settings");awaitDestroyed(practice);focused(owner);assertEquals(off,draft(owner));
   assertEquals(0,engineOpens.get());assertEquals(0,clockOpens.get());assertEquals(0,alarmSchedules.get());assertNull(f.storage.load());assertEquals(0,f.shown);assertEquals(0,f.rings);assertEquals(0,f.schedules);assertEquals(0,f.cancels);
   File folder=new File(c.getExternalFilesDir(null),"verification");try(java.io.PrintWriter out=new java.io.PrintWriter(new File(folder,"wake-check-practice-proof.json"),"UTF-8")){out.println(new org.json.JSONObject().put("real_check_engine_opens",engineOpens.get()).put("runtime_clock_opens",clockOpens.get()).put("alarm_schedule_calls",alarmSchedules.get()).put("real_check_state_absent",f.storage.load()==null).put("draft_preserved_on_return_and_recreation",true).put("off_stays_off",true).put("private_acknowledgement_recreated",true).put("actual_alarm_started",false).toString(2));}
  }
 }
 private void launch(String nonce)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(WakeCheckActivity.class.getName(),null,false);try{c.startActivity(WakeChecks.intent(c,nonce).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(WakeCheckActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}i.waitForIdleSync();}
 private void recreate(String expected)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(WakeCheckActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(WakeCheckActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}text(expected);}
 private void text(String value){assertTrue(value,device.wait(Until.hasObject(By.text(value)),5000));}
 private void click(String value)throws Exception{UiObject2 button=device.wait(Until.findObject(By.text(value)),2000);if(button==null)button=device.wait(Until.findObject(By.desc(value)),1000);if(button==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(value,scroll.exists());scroll.scrollIntoView(new UiSelector().text(value));button=device.wait(Until.findObject(By.text(value)),3000);}assertNotNull(value,button);button.click();device.waitForIdle();}
 private void countdown(String value){i.runOnMainSync(()->{android.widget.TextView timer=activity.findViewById(android.R.id.content).findViewWithTag("wake-check-countdown");assertNotNull(timer);assertEquals(android.view.Gravity.CENTER,timer.getGravity());});assertTrue("Countdown "+value,device.wait(Until.hasObject(By.desc("Wake-up check countdown").text(value)),5000));}
 private void finish()throws Exception{i.runOnMainSync(activity::finish);i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());}
 private void fullConfirmation(){i.runOnMainSync(()->{ArrayList<View> targets=new ArrayList<>();activity.getWindow().getDecorView().findViewsWithText(targets,"I'm awake",View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);assertEquals("One actual acknowledgement target",1,targets.size());View button=targets.get(0);android.graphics.Rect bounds=new android.graphics.Rect();assertTrue(button.isEnabled());assertTrue(button.getGlobalVisibleRect(bounds));assertEquals("Whole acknowledgement width",button.getWidth(),bounds.width());assertEquals("Whole acknowledgement height",button.getHeight(),bounds.height());assertTrue(bounds.height()>=Design.dp(c,64));assertTrue(bounds.width()>=Design.dp(c,48));});}
 private void capture(String suffix)throws Exception{
  CountDownLatch frame=new CountDownLatch(1);boolean[] attached={false};long until=SystemClock.elapsedRealtime()+5000;
  while(!attached[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();attached[0]=true;}}});if(!attached[0])SystemClock.sleep(50);}
  assertTrue("Focused actual check window",attached[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));
  if(suffix.equals("prompt")||suffix.equals("countdown")||suffix.equals("recreated"))fullConfirmation();
  i.runOnMainSync(()->{
   android.widget.LinearLayout footer=activity.getWindow().getDecorView().findViewWithTag("wake-check-footer");assertNotNull("Actual bottom panel",footer);View column=(View)footer.getParent();
   android.graphics.Rect visible=new android.graphics.Rect();assertTrue("Complete bottom panel is visible",footer.getGlobalVisibleRect(visible));assertEquals("Bottom panel is not clipped horizontally",footer.getWidth(),visible.width());assertEquals("Bottom panel is not clipped vertically",footer.getHeight(),visible.height());assertEquals("Bottom panel spans the inset-safe column",column.getWidth(),footer.getWidth());
   int[] origin=new int[2],panel=new int[2];column.getLocationOnScreen(origin);footer.getLocationOnScreen(panel);assertEquals("Panel starts at inset-safe column edge",origin[0],panel[0]);
   for(int n=0;n<footer.getChildCount();n++){View child=footer.getChildAt(n);if(child instanceof android.widget.Button&&child.getVisibility()==View.VISIBLE){android.graphics.Rect target=new android.graphics.Rect();assertTrue("Footer action is visible",child.getGlobalVisibleRect(target));assertEquals("Complete footer action width",child.getWidth(),target.width());assertEquals("Complete footer action height",child.getHeight(),target.height());assertTrue("Footer action48dp",target.width()>=Design.dp(c,48)&&target.height()>=Design.dp(c,48));}}
   if(suffix.equals("waiting")||suffix.equals("prompt")||suffix.equals("countdown")||suffix.equals("recreated")){
    View caption=footer.findViewWithTag("wake-check-footer-caption");assertNotNull("Actual explanatory caption",caption);View button=null;for(int n=0;n<footer.getChildCount();n++)if(footer.getChildAt(n) instanceof android.widget.Button){button=footer.getChildAt(n);break;}assertNotNull(button);
    int[] action=new int[2],copy=new int[2];button.getLocationOnScreen(action);caption.getLocationOnScreen(copy);assertEquals("Reference caption has a10dp gap below its action",Design.dp(c,10),copy[1]-action[1]-button.getHeight());android.graphics.Rect captionBounds=new android.graphics.Rect();assertTrue("Full explanatory caption remains visible",caption.getGlobalVisibleRect(captionBounds));assertEquals(caption.getHeight(),captionBounds.height());assertEquals(caption.getWidth(),captionBounds.width());
   }
  });
  File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"wake-check-"+suffix+".png")));
 }
 @Test public void silentPromptCountsDownRecreatesConfirmsAndReopensDurably()throws Exception{try(Fixture f=new Fixture()){f.arm();launch(f.nonce);text("Check scheduled");countdown("1:00");assertEquals(0,f.shown);assertEquals(0,f.rings);assertFalse(device.hasObject(By.text("I'm awake")));assertFalse(device.hasObject(By.desc("I'm awake")));capture("waiting");i.runOnMainSync(()->{f.clock.advance(60000);f.engine.receive(f.nonce,WakeCheckEngine.Stage.PROMPT);});text("Still awake?");countdown("2:00");capture("prompt");assertEquals(1,f.shown);assertEquals(0,f.rings);long deadline=f.storage.load().deadlineElapsed;i.runOnMainSync(()->f.clock.advance(45000));countdown("1:15");capture("countdown");recreate("Still awake?");countdown("1:15");assertEquals(deadline,f.storage.load().deadlineElapsed);capture("recreated");click("I'm awake");text("You're awake");assertEquals(WakeCheckState.Phase.CONFIRMED,f.storage.load().phase);assertEquals(0,f.storage.prefs.getInt("checkPending",-1));capture("confirmed");finish();i.runOnMainSync(()->f.clock.advance(120000));f.engine.receive(f.nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(0,f.rings);launch(f.nonce);text("You're awake");capture("reopened");finish();String valid=f.storage.prefs.getString(WakeCheckStorage.KEY,"");assertTrue(f.storage.prefs.edit().putString(WakeCheckStorage.KEY,"{broken").commit());launch(f.nonce);text("Saved wake-up check could not be read.");capture("storage-error");assertEquals(0,f.rings);assertEquals(1,f.shown);finish();assertTrue(f.storage.prefs.edit().putString(WakeCheckStorage.KEY,valid).commit());}}
 @Test public void deniedAndDeliveryErrorRetryKeepDeadlineExpiryFiresOnlyFakeOwnedAlarm()throws Exception{try(Fixture f=new Fixture()){f.allow=false;f.arm();launch(f.nonce);text("Check needs attention");text("Allow notifications to receive the silent check.");assertEquals(0,f.schedules);assertEquals(0,f.shown);capture("access-error");i.runOnMainSync(()->{f.allow=true;f.failShow=true;f.clock.advance(60000);});click("Retry check");text("The silent check could not be shown. Open notification settings, then retry.");long deadline=f.storage.load().deadlineElapsed;capture("delivery-error");i.runOnMainSync(()->{f.failShow=false;f.clock.advance(30000);});click("Retry check");text("Still awake?");countdown("1:30");assertEquals(deadline,f.storage.load().deadlineElapsed);assertEquals(f.nonce,f.storage.load().nonce);assertEquals(1,f.shown);capture("retry");i.runOnMainSync(()->f.clock.advance(90000));text("Check missed");assertEquals(1,f.rings);assertEquals(WakeCheckState.Phase.EXPIRED,f.storage.load().phase);f.engine.receive(f.nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(1,f.rings);capture("expired");finish();String next=UUID.randomUUID().toString();f.engine.arm(WakeCheckState.waiting(next,f.run,f.alarm.json().toString(),f.alarm.label,1,60000,false,f.clock));launch(f.nonce);text("This check is no longer active.");capture("stale");assertEquals(next,f.storage.load().nonce);assertEquals(WakeCheckState.Phase.WAITING,f.storage.load().phase);assertEquals(1,f.rings);finish();verifyPostSaveOffCancellation(f,next);}}
 private void verifyPostSaveOffCancellation(Fixture f,String pending)throws Exception{Alarm other;String untouched;try(Store store=new Store(c,f.database)){other=store.alarm(2);untouched=other.json().toString();}AlarmEditorActivity editor=editor(other);click("Save alarm");awaitDestroyed(editor);assertEquals("Saving unrelated Off alarm cannot cancel pending check",pending,f.storage.load().nonce);assertEquals(WakeCheckState.Phase.WAITING,f.storage.load().phase);editor=editor(f.alarm);click("Snooze");UiObject2 check=device.wait(Until.findObject(By.desc("Wake-up check")),2000);if(check==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description("Wake-up check"));check=device.wait(Until.findObject(By.desc("Wake-up check")),3000);}assertNotNull(check);check.click();assertTrue(device.wait(Until.hasObject(By.desc("Options for Wake-up check")),3000));UiObject2 off=device.wait(Until.findObject(By.desc("Off")),3000);assertNotNull(off);off.click();assertTrue(device.wait(Until.gone(By.desc("Options for Wake-up check")),3000));click("Save changes");f.failAlarmSave=true;click("Save alarm");assertFalse("Failed persistence preserves editor draft",editor.isDestroyed());editorError(editor);assertEquals(WakeCheckState.Phase.WAITING,f.storage.load().phase);try(Store store=new Store(c,f.database)){assertEquals(1,store.alarm(1).awakeCheck);assertEquals(untouched,store.alarm(2).json().toString());}f.failAlarmSave=false;click("Save alarm");awaitDestroyed(editor);assertEquals(WakeCheckState.Phase.CANCELLED,f.storage.load().phase);try(Store store=new Store(c,f.database)){assertEquals(0,store.alarm(1).awakeCheck);assertEquals(untouched,store.alarm(2).json().toString());assertEquals(0,store.backup().getJSONArray("sessions").length());f.before=store.backup().toString();}}
 private void editorError(AlarmEditorActivity editor)throws Exception{UiObject2 error=device.wait(Until.findObject(By.desc("Alarm save error")),5000);assertNotNull("Persistent inline error after failed save",error);assertTrue(error.getText().contains("could not be saved"));assertTrue(error.getVisibleBounds().height()>0);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View view=editor.getWindow().getDecorView();assertTrue(editor.hasWindowFocus());view.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);view.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"wake-check-editor-save-error.png")));}
 private AlarmEditorActivity editor(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor m=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));AlarmEditorActivity a=(AlarmEditorActivity)m.waitForActivityWithTimeout(5000);assertNotNull(a);text("Edit alarm");return a;}finally{i.removeMonitor(m);}}
 private void awaitDestroyed(Activity a){long until=SystemClock.elapsedRealtime()+5000;while(!a.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(a.isDestroyed());}
}
